import java.io.BufferedWriter;
import java.io.FileReader;
import java.io.FileWriter;

public class Main {
    public static void main(String[] args) throws Exception {
        BufferedWriter 笔 = new BufferedWriter(new FileWriter("两趟.txt"));

        for (int i = 1; i <= 2; i++) {
            笔.write("第 " + i + " 行");
            笔.newLine();
        }
        笔.flush();

        BufferedReader 眼一 = new BufferedReader(new FileReader("两趟.txt"));
        int 一 = 0;
        while (眼一.readLine() != null) {
            一 = 一 + 1;
        }
        眼一.close();
        System.out.println("第一次念到 " + 一 + " 行");

        for (int i = 2 + 1; i <= 2 + 1; i++) {
            笔.write("第 " + i + " 行");
            笔.newLine();
        }
        笔.close();

        BufferedReader 眼二 = new BufferedReader(new FileReader("两趟.txt"));
        int 二 = 0;
        while (眼二.readLine() != null) {
            二 = 二 + 1;
        }
        眼二.close();
        System.out.println("第二次念到 " + 二 + " 行");
    }
}

